#[global_allocator]
static GLOBAL: mimalloc::MiMalloc = mimalloc::MiMalloc;

use anyhow::{Context, Result};
use bidiff::DiffParams;
use clap::Parser;
use memmap2::Mmap;
use std::{
    fs::File,
    io::{BufWriter, Write},
    path::PathBuf,
    time::Instant,
};
use tracing::info;

/// Generate and apply binary patches
#[derive(Parser, Debug)]
struct Cli {
    #[command(subcommand)]
    cmd: Command,
}

#[derive(clap::Subcommand, Debug)]
enum Command {
    /// Write the diff of two files to a patch file
    Diff(Diff),
    /// Apply a patch file generated by this tool
    Patch(Patch),
    /// Round-trip verification (diff then patch)
    Cycle(Cycle),
    /// Print a patch's format version and the sizes and BLAKE3 hashes of its
    /// base and result
    Info(Info),
}

#[derive(Parser, Debug, Clone)]
struct Diff {
    older: PathBuf,
    newer: PathBuf,
    patch: PathBuf,
    /// Hash index block size (minimum 4)
    #[arg(long, default_value_t = 32)]
    block_size: usize,
    /// Scan chunk size in MB (default: 1)
    #[arg(long, default_value_t = 1)]
    scan_chunk_mb: usize,
    /// Max threads for parallel scanning (default: all cores)
    #[arg(long)]
    threads: Option<usize>,
    /// Maximize compression (zstd level 22); slower but ~30% smaller patches
    #[arg(long)]
    max: bool,
    /// Keep hash table in RAM (faster but uses ~500 MB+ for large files)
    #[arg(long)]
    ram: bool,
}

#[derive(Parser, Debug)]
struct Patch {
    older: PathBuf,
    patch: PathBuf,
    output: PathBuf,
    /// Refuse the patch unless its result is this many bytes
    #[arg(long)]
    expect_size: Option<u64>,
    /// Refuse the patch unless its result has this BLAKE3 hash (hex, as b3sum prints)
    #[arg(long, value_parser = parse_hash)]
    expect_hash: Option<blake3::Hash>,
}

fn parse_hash(s: &str) -> Result<blake3::Hash, blake3::HexError> {
    blake3::Hash::from_hex(s)
}

#[derive(Parser, Debug)]
struct Info {
    patch: PathBuf,
}

#[derive(Parser, Debug)]
struct Cycle {
    older: PathBuf,
    newer: PathBuf,
    /// Hash index block size (minimum 4)
    #[arg(long, default_value_t = 32)]
    block_size: usize,
    /// Scan chunk size in MB (default: 1)
    #[arg(long, default_value_t = 1)]
    scan_chunk_mb: usize,
    /// Max threads for parallel scanning (default: all cores)
    #[arg(long)]
    threads: Option<usize>,
    /// Maximize compression (zstd level 22); slower but ~30% smaller patches
    #[arg(long)]
    max: bool,
    /// Keep hash table in RAM (faster but uses ~500 MB+ for large files)
    #[arg(long)]
    ram: bool,
    /// Also measure peak anonymous RSS (runs a separate diff pass with a polling thread)
    #[arg(long)]
    with_anon: bool,
}

/// Read anonymous RSS (heap + anonymous mmap).
/// Excludes file-backed mmap pages — only counts "real" memory allocations.
#[cfg(target_os = "linux")]
fn read_rss_anon() -> u64 {
    std::fs::read_to_string("/proc/self/status")
        .ok()
        .and_then(|s| {
            s.lines()
                .find(|l| l.starts_with("RssAnon:"))?
                .split_whitespace()
                .nth(1)?
                .parse::<u64>()
                .ok()
        })
        .map(|kb| kb * 1024)
        .unwrap_or(0)
}

/// Read anonymous RSS via mach task_info (TASK_VM_INFO).
/// The `internal` field counts anonymous memory in bytes.
#[cfg(target_os = "macos")]
fn read_rss_anon() -> u64 {
    use mach_sys::kern_return::KERN_SUCCESS;
    use mach_sys::task::task_info;
    use mach_sys::task_info::{TASK_VM_INFO, TASK_VM_INFO_COUNT, task_vm_info_t};
    use mach_sys::traps::mach_task_self;
    use std::mem::MaybeUninit;
    unsafe {
        let mut info = MaybeUninit::<task_vm_info_t>::uninit();
        let mut count = TASK_VM_INFO_COUNT;
        let kr = task_info(
            mach_task_self(),
            TASK_VM_INFO,
            info.as_mut_ptr() as *mut _,
            &mut count,
        );
        if kr != KERN_SUCCESS {
            return 0;
        }
        let info = info.assume_init();
        info.internal as u64
    }
}

#[cfg(not(any(target_os = "linux", target_os = "macos")))]
fn read_rss_anon() -> u64 {
    0
}

fn format_size(bytes: u64) -> String {
    if bytes >= 1024 * 1024 {
        format!("{:.1} MiB", bytes as f64 / (1024.0 * 1024.0))
    } else if bytes >= 1024 {
        format!("{:.0} KiB", bytes as f64 / 1024.0)
    } else {
        format!("{} B", bytes)
    }
}

fn main() -> Result<()> {
    tracing_subscriber::fmt::init();

    let Cli { cmd } = Cli::parse();
    match cmd {
        Command::Diff(args) => {
            do_diff(&args)?;
        }
        Command::Patch(args) => {
            do_patch(&args)?;
        }
        Command::Cycle(args) => {
            do_cycle(&args)?;
        }
        Command::Info(args) => {
            do_info(&args)?;
        }
    }

    Ok(())
}

fn do_cycle(
    Cycle {
        older,
        newer,
        block_size,
        scan_chunk_mb,
        threads,
        max,
        ram,
        with_anon,
    }: &Cycle,
) -> Result<()> {
    let newer_mmap = mmap_file(newer)?;
    info!(
        "Before {}, After {}",
        format_size(std::fs::metadata(older)?.len()),
        format_size(newer_mmap.len() as u64),
    );

    let diff_args = Diff {
        older: older.clone(),
        newer: newer.clone(),
        patch: PathBuf::new(), // filled in below
        block_size: *block_size,
        scan_chunk_mb: *scan_chunk_mb,
        threads: *threads,
        max: *max,
        ram: *ram,
    };

    // Separate anon RSS measurement pass (if requested) — uses a polling thread
    // so we don't contaminate the timing run.
    let peak_mem = if *with_anon {
        use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};
        let peak_anon = std::sync::Arc::new(AtomicU64::new(0));
        let done = std::sync::Arc::new(AtomicBool::new(false));
        let peak_clone = peak_anon.clone();
        let done_clone = done.clone();
        std::thread::spawn(move || {
            while !done_clone.load(Ordering::Relaxed) {
                peak_clone.fetch_max(read_rss_anon(), Ordering::Relaxed);
                std::thread::sleep(std::time::Duration::from_millis(5));
            }
        });
        let anon_tmp = tempfile::NamedTempFile::new().context("create anon tempfile")?;
        do_diff(&Diff {
            patch: anon_tmp.path().to_path_buf(),
            ..diff_args.clone()
        })?;
        done.store(true, Ordering::Release);
        Some(peak_anon.load(Ordering::Acquire))
    } else {
        None
    };

    let patch_tmp = tempfile::NamedTempFile::new().context("create patch tempfile")?;
    let output_tmp = tempfile::NamedTempFile::new().context("create output tempfile")?;
    let patch_path = patch_tmp.path().to_path_buf();
    let output_path = output_tmp.path().to_path_buf();

    let before_diff = Instant::now();
    do_diff(&Diff {
        patch: patch_path.clone(),
        ..diff_args
    })?;
    let diff_duration = before_diff.elapsed();

    let compatch_size = std::fs::metadata(&patch_path)?.len();

    let newer_hash = blake3::hash(&newer_mmap[..]);
    let before_patch = Instant::now();
    do_patch(&Patch {
        older: older.clone(),
        patch: patch_path,
        output: output_path.clone(),
        expect_size: Some(newer_mmap.len() as u64),
        expect_hash: Some(newer_hash),
    })?;
    let patch_duration = before_patch.elapsed();

    let fresh = mmap_file(&output_path)?;
    anyhow::ensure!(fresh.len() == newer_mmap.len(), "Size mismatch!");
    let fresh_hash = blake3::hash(&fresh[..]);
    anyhow::ensure!(newer_hash == fresh_hash, "Hash mismatch!");

    let ratio = (compatch_size as f64) / (newer_mmap.len() as f64);
    let cp = format!("patch {}", format_size(compatch_size));
    let cr = format!(
        "{:03.3}% of {}",
        ratio * 100.0,
        format_size(newer_mmap.len() as u64)
    );
    let cdd = format!("dtime {:?}", diff_duration);
    let cpd = format!("ptime {:?}", patch_duration);
    if let Some(mem) = peak_mem {
        let cmem = format!("anon {}", format_size(mem));
        println!(
            "{:12} {:20} {:27} {:20} {:20} {:20}",
            "zstd", cp, cr, cdd, cpd, cmem
        );
    } else {
        println!("{:12} {:20} {:27} {:20} {:20}", "zstd", cp, cr, cdd, cpd);
    }

    Ok(())
}

fn do_patch(
    Patch {
        older,
        patch,
        output,
        expect_size,
        expect_hash,
    }: &Patch,
) -> Result<()> {
    let start = Instant::now();

    let patch_data = mmap_file(patch)?;
    let patch = bidiff::patch::read_patch(&patch_data).context("read patch")?;
    let size = expect_size.unwrap_or(patch.new_size());
    let hash = expect_hash.unwrap_or(patch.new_hash());
    let patch = patch.expect(size, hash).context("check expected result")?;
    let older = mmap_file(older)?;
    let base = patch.verify_base(&older).context("check base file")?;

    write_output(output, patch.new_size(), |file| {
        base.apply_to_file(file).context("apply patch")?;
        Ok(())
    })?;

    info!("Completed in {:?}", start.elapsed());

    Ok(())
}

/// Create `path`, pre-size it to `size` bytes and fill it with `fill`. The
/// file is removed if `fill` fails, so a bad patch leaves no
/// plausible-looking output.
fn write_output(path: &PathBuf, size: u64, fill: impl FnOnce(&File) -> Result<()>) -> Result<()> {
    let output_file = File::options()
        .read(true)
        .write(true)
        .create(true)
        .truncate(true)
        .open(path)
        .context("create output file")?;
    let result = presize(&output_file, size).and_then(|()| fill(&output_file));
    if result.is_err() {
        drop(output_file);
        std::fs::remove_file(path).ok();
    }
    result
}

fn presize(file: &File, size: u64) -> Result<()> {
    #[cfg(target_os = "linux")]
    {
        use std::os::unix::io::AsRawFd;
        // fallocate pre-allocates disk blocks, avoiding per-page block allocation during writes.
        // Falls back to ftruncate on failure (e.g. tmpfs).
        let len = i64::try_from(size).context("output size")?;
        if unsafe { libc::fallocate(file.as_raw_fd(), 0, 0, len) } != 0 {
            file.set_len(size).context("pre-size output file")?;
        }
    }
    #[cfg(not(target_os = "linux"))]
    let _ = (file, size);
    Ok(())
}

fn do_info(Info { patch }: &Info) -> Result<()> {
    let data = mmap_file(patch)?;
    let patch = bidiff::patch::read_patch(&data).context("read patch")?;
    println!("format  {:#X}", bidiff::VERSION);
    println!("base    {}  {} bytes", patch.old_hash(), patch.old_size());
    println!("result  {}  {} bytes", patch.new_hash(), patch.new_size());
    println!("chunks  {}", patch.chunks().len());
    Ok(())
}

fn mmap_file(path: &PathBuf) -> Result<Mmap> {
    let file = File::open(path).with_context(|| format!("open {}", path.display()))?;
    let mmap = unsafe { memmap2::MmapOptions::new().populate().map(&file) }
        .with_context(|| format!("mmap {}", path.display()))?;
    #[cfg(target_os = "linux")]
    mmap.advise(memmap2::Advice::HugePage).ok();
    Ok(mmap)
}

fn do_diff(
    Diff {
        older,
        newer,
        patch,
        block_size,
        scan_chunk_mb,
        threads,
        max,
        ram,
    }: &Diff,
) -> Result<()> {
    let start = Instant::now();

    let older_contents = mmap_file(older)?;
    #[cfg(unix)]
    older_contents.advise(memmap2::Advice::Random).ok();
    let newer_contents = mmap_file(newer)?;
    #[cfg(unix)]
    newer_contents.advise(memmap2::Advice::Sequential).ok();

    let scan_chunk_size = Some(scan_chunk_mb * 1024 * 1024);
    let mut diff_params = DiffParams::with_threads(*block_size, scan_chunk_size, *threads).unwrap();
    diff_params.use_ram = *ram;
    let zstd_level = if *max { 22 } else { 3 };
    let mut out = BufWriter::new(File::create(patch).context("create patch file")?);
    bidiff::simple_diff_chunked_with_params(
        &older_contents[..],
        &newer_contents[..],
        &mut out,
        &diff_params,
        zstd_level,
    )
    .context("chunked diff")?;
    out.flush().context("finish writing patch file")?;

    info!("Completed in {:?}", start.elapsed());

    Ok(())
}
